package com.yigongbao.backup.order;
import cn.dev33.satoken.stp.StpUtil; import com.fasterxml.jackson.databind.ObjectMapper; import com.yigongbao.backup.common.ApiResponse; import com.yigongbao.backup.job.*; import com.yigongbao.backup.storage.api.ArtifactStore; import lombok.RequiredArgsConstructor; import org.springframework.core.io.InputStreamResource; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.io.FileNotFoundException; import java.io.IOException; import java.nio.file.*; import java.util.List; import java.util.UUID;
/** 普通用户订单补传接口；第一期只上传和下载，不提供删除。 */
@RestController @RequestMapping("/api/v1/orders/{orderId}/supplements") @RequiredArgsConstructor
public class SupplementController {private final SupplementService supplements; private final OrderSnapshotMapper snapshots; private final ArtifactStore store; private final PersistentJobCoordinator jobs; private final ObjectMapper mapper; private static String rid(){return UUID.randomUUID().toString();}
 @GetMapping public ApiResponse<List<SupplementService.SupplementInfo>> list(@PathVariable("orderId") String orderId) throws IOException {StpUtil.checkLogin();SnapshotRef ref=snapshot(orderId);return ApiResponse.ok(supplements.listForSnapshot(ref.id(),ref.code()),rid());}
 @PostMapping public ApiResponse<UploadTask> upload(@PathVariable("orderId") String orderId,@RequestPart("file") MultipartFile file) throws IOException {StpUtil.checkLogin();if(file.isEmpty())throw new IllegalArgumentException("补传文件为空");SnapshotRef ref=snapshot(orderId);long actor=StpUtil.getLoginIdAsLong();Path staging=store.root().resolve(".supplement-staging").normalize();if(!staging.startsWith(store.root()))throw new IllegalStateException("补传暂存目录非法");Files.createDirectories(staging);Path staged=Files.createTempFile(staging,"upload-",".part");try{file.transferTo(staged);SupplementUploadJobHandler.Payload payload=new SupplementUploadJobHandler.Payload(ref.id(),ref.code(),file.getOriginalFilename(),file.getSize(),file.getContentType(),null,staged.toString());String json=mapper.writeValueAsString(payload);String stable=ref.id()+"\n"+file.getOriginalFilename()+"\n"+file.getSize()+"\n"+sha256(staged);JobEntity j=jobs.create("SUPPLEMENT_UPLOAD",JobIdempotency.key("SUPPLEMENT_UPLOAD",actor,stable),actor,json);if(!java.util.Objects.equals(j.getConfigSnapshotJson(),json))Files.deleteIfExists(staged);return ApiResponse.ok(new UploadTask(j.getId(),j.getJobNo(),j.getStatus(),file.getOriginalFilename(),file.getSize()),rid());}catch(Exception e){Files.deleteIfExists(staged);if(e instanceof IOException io)throw io;throw new IllegalStateException("补传任务创建失败",e);}}
 @GetMapping("/{fileId}/download") public ResponseEntity<?> download(@PathVariable("orderId") String orderId,@PathVariable("fileId") String fileId) throws IOException {StpUtil.checkLogin(); try {SnapshotRef ref=snapshot(orderId);return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+fileId+"\"").body(new InputStreamResource(supplements.openForSnapshot(ref.id(),fileId)));} catch(NoSuchFileException|FileNotFoundException e){return ResponseEntity.notFound().build();}}
 private SnapshotRef snapshot(String id){if(id==null||!id.matches("[0-9]{1,19}"))throw new IllegalArgumentException("订单标识非法");long snapshotId;try{snapshotId=Long.parseLong(id);}catch(NumberFormatException e){throw new IllegalArgumentException("订单标识非法",e);}OrderSnapshotEntity snapshot=snapshots.selectById(snapshotId);if(snapshot==null||snapshot.getOrderCode()==null)throw new IllegalArgumentException("订单不存在");return new SnapshotRef(snapshotId,snapshot.getOrderCode());}
 private static String sha256(Path file)throws Exception{var digest=java.security.MessageDigest.getInstance("SHA-256");try(var in=Files.newInputStream(file)){byte[] buffer=new byte[8192];for(int n;(n=in.read(buffer))>=0;)if(n>0)digest.update(buffer,0,n);}return java.util.HexFormat.of().formatHex(digest.digest());}
 private record SnapshotRef(long id,String code){}
 public record UploadTask(Long jobId,String jobNo,String status,String fileName,long size){}
}
